const params=new URLSearchParams(location.search),id=params.get('id'),$=s=>document.querySelector(s),esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function safeUrl(url){try{const value=new URL(url,location.href);return['http:','https:'].includes(value.protocol)?value.href:'#'}catch{return'#'}}
function dimensions(size='300x250'){const[w,h]=size.split('x').map(Number);return{w:w||300,h:h||250}}
function isolatedAdUrl(code){const html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="strict-origin-when-cross-origin"><base target="_blank"><style>html,body{margin:0;background:transparent;overflow:hidden;display:flex;justify-content:center}img,iframe{max-width:100%}</style></head><body>${code}</body></html>`;return`data:text/html;charset=utf-8,${encodeURIComponent(html)}`}
function renderPageAd(slot,ads){const host=document.querySelector(`[data-page-ad="${slot}"]`),data=ads?.[slot];if(!host||!data?.active){if(host)host.hidden=true;return}const size=data.size||'300x250',dim=dimensions(size);host.dataset.size=size;host.style.setProperty('--ad-w',`${dim.w}px`);host.style.setProperty('--ad-h',`${dim.h}px`);const label=document.createElement('span');label.textContent=data.label||'IKLAN';host.append(label);if(data.mode==='code'&&data.code){const frame=document.createElement('iframe');frame.title=data.label||'Iklan';frame.referrerPolicy='strict-origin-when-cross-origin';frame.src=isolatedAdUrl(data.code);host.append(frame)}else{const link=document.createElement('a');link.href=safeUrl(data.url);link.target='_blank';link.rel='noopener noreferrer sponsored';if(data.image){const img=document.createElement('img');img.src=data.image;img.alt=data.label||'Iklan';link.append(img)}else{link.className='page-ad-placeholder';link.innerHTML='<b>Ruang iklan</b><small>Atur dari halaman admin</small>'}host.append(link)}}
function showMissing(){$('#wait-page').innerHTML='<section class="not-found"><span class="eyebrow"><i></i> Link tidak tersedia</span><h1>Mod tidak ditemukan</h1><p>Kembali ke katalog dan pilih mod yang masih aktif.</p><a class="button primary" href="index.html#koleksi">Kembali ke katalog</a></section>'}
function setupWait(item){document.title=`Ruang Tunggu — ${item.title}`;$('#back-detail').href=NMData.detailUrl(item.id);$('#wait-mod').innerHTML=`<b>${esc(item.title)}</b><span>${esc(item.version)} · ${esc(item.platform)} · ${esc(item.size)}</span>`;const storageKey=`nm-download-wait-${item.id}`;let state;try{state=JSON.parse(sessionStorage.getItem(storageKey)||'null')}catch{}if(!state?.readyAt){const seconds=10+Math.floor(Math.random()*21);state={readyAt:Date.now()+seconds*1000};sessionStorage.setItem(storageKey,JSON.stringify(state))}const button=$('#final-download'),number=$('#timer-number');function unlock(){number.textContent='✓';number.nextElementSibling.textContent='siap';$('#unlock-title').textContent='Link download sudah siap';$('#unlock-copy').textContent='Klik tombol di bawah untuk membuka sumber mod pada tab baru.';button.textContent='Buka link mod ↗';button.href=safeUrl(item.link);button.target='_blank';button.rel='noopener noreferrer';button.classList.remove('disabled');button.setAttribute('aria-disabled','false')}function tick(){const left=Math.max(0,Math.ceil((state.readyAt-Date.now())/1000));number.textContent=left;if(left<=0){unlock();return}setTimeout(tick,250)}tick();button.addEventListener('click',e=>{if(button.getAttribute('aria-disabled')==='true'||safeUrl(item.link)==='#'){e.preventDefault();return}NMData.incrementClicks(item.id)})}
$('#year').textContent=new Date().getFullYear();
(async()=>{try{const[item,settings]=await Promise.all([id?NMData.getMod(id):null,NMData.getSettings()]);['top','inline1','inline2','bottom'].forEach(slot=>renderPageAd(slot,settings.ads));if(!item)return showMissing();setupWait(item)}catch(error){showMissing()}})();
